import { Entry, manual, Pipeline, Project, ShellStep } from "@sverka/workflow";

// Verification pipeline for @sverka/storage. Every check the package supports,
// in dependency order: format -> lint -> typecheck -> test -> build.
// Run locally with `bun run verify`.
const project = new Project("storage");

const verify = new Pipeline(project, "verify", {
  name: "verify",
});

new ShellStep(verify, "format", { command: "bun run format" });
new ShellStep(verify, "lint", {
  command: "bun run lint",
  dependsOn: ["format"],
});
new ShellStep(verify, "typecheck", {
  command: "bun run typecheck",
  dependsOn: ["lint"],
});
new ShellStep(verify, "test", {
  command: "bun run test",
  dependsOn: ["typecheck"],
});
new ShellStep(verify, "build", {
  command: "bun run build",
  dependsOn: ["test"],
});

new Entry(verify, "manual", { trigger: manual(), roots: ["build"] });

export default project;

// Local runner for the verification pipeline declared in sverka.config.ts.
// Synthesizes the pipeline into a Definition Graph, binds a run plan for the
// manual entry, and executes it with the native engine's host driver.

import { mkdir } from "node:fs/promises";
import { join } from "node:path";
import {
  createAllowlist,
  createEngine,
  createHostDriver,
} from "@sverka/runtime";
import {
  collectConstructWarnings,
  computeGraphId,
  computeRunPlanId,
  synthesize,
  validateGraph,
  type RunPlan,
  type StepDefinition,
} from "@sverka/workflow";
import project from "../sverka.config.ts";

const PIPELINE_ID = "verify";
const workspace = process.cwd();
const artifactDir = join(workspace, ".sverka", "verify");

for (const warning of collectConstructWarnings(project)) {
  console.warn(`[verify] config warning: ${warning}`);
}

const graph = synthesize(project);
validateGraph(graph);

const pipeline = graph.project.pipelines.find((p) => p.id === PIPELINE_ID);
if (!pipeline) {
  throw new Error(`pipeline '${PIPELINE_ID}' not found in sverka.config.ts`);
}
const entry = pipeline.entries[0];
if (!entry) {
  throw new Error(`pipeline '${PIPELINE_ID}' declares no entries`);
}

// Collect the steps reachable from the entry's roots through dependencies.
const byId = new Map(pipeline.steps.map((s) => [s.id, s]));
const reachable = new Set<string>();
const stack = [...entry.roots];
while (stack.length > 0) {
  const id = stack.pop() as string;
  if (reachable.has(id)) continue;
  const step = byId.get(id);
  if (!step) {
    throw new Error(`entry '${entry.id}' references unknown step '${id}'`);
  }
  reachable.add(id);
  for (const dep of step.dependencies) stack.push(dep.producer);
}
const steps: StepDefinition[] = pipeline.steps.filter((s) =>
  reachable.has(s.id),
);

const draft = {
  apiVersion: "sverka.dev/v1run",
  graphId: computeGraphId(graph),
  entry: { id: entry.id, trigger: entry.trigger },
  inputs: {},
  steps,
} as const;
const plan: RunPlan = {
  ...draft,
  id: computeRunPlanId(draft),
  createdAt: new Date().toISOString(),
};

await mkdir(artifactDir, { recursive: true });

const driver = createHostDriver({
  enabled: true,
  allowlist: createAllowlist(["bun"]),
  envAllowlist: [
    "PATH",
    "HOME",
    "TMPDIR",
    "TEMP",
    "TMP",
    "USER",
    "LANG",
    "TERM",
    "NO_COLOR",
    "FORCE_COLOR",
    "XDG_CACHE_HOME",
    "BUN_INSTALL",
  ],
  env: { CI: "true" },
});
const engine = createEngine({ drivers: [driver] });

function printLog(label: string, text: string | undefined): void {
  if (text && text.length > 0) console.error(`[verify] ${label}: ${text.trimEnd()}`);
}

let status = "failure";
try {
  for await (const event of engine.run({ plan, workspace, artifactDir })) {
    switch (event.type) {
      case "step-started":
        console.log(`[verify] ${event.stepId} — started`);
        break;
      case "step-succeeded":
        printLog(`${event.stepId} stdout`, event.stdout);
        console.log(
          `[verify] ${event.stepId} — ok (${event.durationMs}ms)`,
        );
        break;
      case "step-skipped":
        console.log(`[verify] ${event.stepId} — skipped`);
        break;
      case "step-cancelled":
        console.log(`[verify] ${event.stepId} — cancelled`);
        break;
      case "step-failed":
        console.error(`[verify] ${event.stepId} — failed: ${event.error}`);
        printLog(`${event.stepId} stdout`, event.stdout);
        printLog(`${event.stepId} stderr`, event.stderr);
        break;
      case "diagnostic":
        console.warn(`[verify] ${event.stepId}: ${event.message}`);
        break;
      case "run-completed":
        status = event.status;
        console.log(`[verify] run ${event.status} in ${event.durationMs}ms`);
        break;
    }
  }
} catch (err) {
  await engine.cancel();
  throw err;
}

if (status !== "success") {
  console.error(`[verify] pipeline ${status}`);
  process.exitCode = 1;
} else {
  console.log("[verify] all checks passed");
}

import { Project, Pipeline, ShellStep, Entry, push } from "@sverka/workflow";

const proj = new Project("verify");
const ci = new Pipeline(proj, "ci");

// Fast checks first (parallel, no deps)
new ShellStep(ci, "format", { command: "bun run format" });
new ShellStep(ci, "lint", { command: "bun run lint" });
new ShellStep(ci, "typecheck", { command: "bun run typecheck" });

// Test depends on fast checks
new ShellStep(ci, "test", {
  command: "bun run test",
  dependsOn: ["format", "lint", "typecheck"],
});

// Build depends on test
new ShellStep(ci, "build", { command: "bun run build", dependsOn: ["test"] });

new Entry(ci, "on-push", { trigger: push(), roots: ["build"] });

export default proj;

